import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_kernel(const float* input, const float* bias, float* output, int C, int H, int W) {
    extern __shared__ float shared_data[];

    int batch_idx = blockIdx.x;
    int channel_idx = threadIdx.x;

    if (channel_idx >= C) return;

    const float* channel_data = input + batch_idx * C * H * W + channel_idx * H * W;
    float sum = 0.0f;

    for (int i = 0; i < H * W; ++i) {
        sum += channel_data[i];
    }

    float mean = sum / (H * W);
    float biased_mean = mean + bias[channel_idx];

    shared_data[channel_idx] = biased_mean;
    __syncthreads();

    // Log-sum-exp reduction
    float max_val = -INFINITY;
    for (int i = 0; i < C; ++i) {
        max_val = fmaxf(max_val, shared_data[i]);
    }

    float sum_exp = 0.0f;
    for (int i = 0; i < C; ++i) {
        sum_exp += expf(shared_data[i] - max_val);
    }

    float log_sum_exp = max_val + logf(sum_exp);
    float result = log_sum_exp * 10.0f;

    if (channel_idx == 0) {
        output[batch_idx] = result;
    }
}

torch::Tensor fused_operation_cuda(torch::Tensor input, torch::Tensor bias) {
    TORCH_CHECK(input.dim() == 4, "Input must be 4D (B, C, H, W)");
    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto output = torch::zeros({B, 1}, input.options());

    dim3 grid(B);
    dim3 block(C);
    size_t shared_mem_size = C * sizeof(float);

    fused_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        C,
        H,
        W
    );

    return output;
}
"""

fused_op_cpp = "torch::Tensor fused_operation_cuda(torch::Tensor input, torch::Tensor bias);"

fused_op_ext = load_inline(
    name='fused_op',
    cpp_sources=fused_op_cpp,
    cuda_sources=fused_op_source,
    functions=['fused_operation_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_op = fused_op_ext

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_op.fused_operation_cuda(x, self.bias)
        return x
